import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"; tok=[None]; log=set()
def get(path):
    for _ in range(200):
        if not tok[0]:
            tok[0]=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST")))["token"]
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok[0]}))
            return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            if e.code==404: return None
            log.add((e.code,body[:80]))
            if e.code==401: tok[0]=None
            elif e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w)
            else: time.sleep(0.5)
        except Exception as e:
            log.add(("exc",str(e)[:60])); time.sleep(0.5)
    raise SystemExit("fail "+path)
orders={};dups=0;p=1;tp=None
while True:
    d=get(f"/orders?page={p}"); tp=d["total_pages"]
    for o in d["items"]:
        if o["id"] in orders:
            dups+=1
            if orders[o["id"]]!=o: log.add(("dupdiff",o["id"]))
        else: orders[o["id"]]=o
    if not d["next"] or p>=tp: break
    p+=1
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in("north","south","east","west")};n=0
for o in orders.values():
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: log.add(("naive",o["id"])); t=t.replace(tzinfo=timezone.utc)
    if not(lo<=t.astimezone(timezone.utc)<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    if cust[c] is None: log.add(("nocust",c)); continue
    a=o["amount_cents"]*(100-cust[c]["discount_pct"])
    v=(a+50)//100
    reg[cust[c]["region"]]+=v;n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res,len(orders),tp,sorted(log,key=str)[:15])
